            Pricing
          </p>
          <h2 className="text-3xl sm:text-4xl font-bold text-foreground mb-4">
            Start free, grow as you hire
          </h2>
          <p className="text-base text-muted-foreground mb-6">
            No commitments. No hidden fees. Cancel anytime.
          </p>
          {/* Toggle */}
          <div className="inline-flex items-center gap-3 bg-card border border-border rounded-full px-4 py-2">
            <span
              className={`text-sm font-medium ${!annual ? "text-foreground" : "text-muted-foreground"}`}
            >
              Monthly
            </span>
            <Switch
              checked={annual}
              onCheckedChange={setAnnual}
              aria-label="Toggle annual billing"
            />
            <span
              className={`text-sm font-medium ${annual ? "text-foreground" : "text-muted-foreground"}`}
            >
              Annual
            </span>
            <Badge variant="success" className="text-[11px] py-0.5">
              Save 20%
            </Badge>
          </div>
        </div>
      </FadeIn>

      <StaggerList
        className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4"
        stagger={0.08}
      >
        {pricingPlans.map((plan) => (
          <div
            key={plan.name}
            className={`rounded-xl border bg-card p-6 flex flex-col gap-5 relative ${
              plan.highlighted
                ? "border-2 border-primary shadow-lg shadow-primary/10"
                : "border-border"
            }`}
          >
            {plan.badge && (
              <Badge className="absolute -top-3 left-1/2 -translate-x-1/2 text-[11px] shadow-sm">
                {plan.badge}
              </Badge>
            )}
            <div>
              <p className="text-sm font-semibold text-foreground">{plan.name}</p>
              <div className="mt-2 flex items-baseline gap-1">
                <span className="text-3xl font-bold text-foreground">
                  ${annual ? plan.annualPrice : plan.monthlyPrice}
                </span>
                {plan.monthlyPrice > 0 && (
                  <span className="text-sm text-muted-foreground">/mo</span>
                )}
              </div>
              {annual && plan.monthlyPrice > 0 && (
                <p className="text-xs text-muted-foreground mt-0.5">
                  billed annually
                </p>
              )}
              <p className="text-xs text-muted-foreground mt-2">
                {plan.description}
              </p>
            </div>

            <div className="flex-1 space-y-2">
              {plan.features.map((f) => (
                <div key={f} className="flex items-start gap-2">
                  <CheckCircle2 className="h-4 w-4 text-success shrink-0 mt-0.5" />
                  <span className="text-xs text-foreground">{f}</span>
                </div>
              ))}
            </div>

            <Button
              variant={plan.highlighted ? "default" : "outline"}
              className="w-full"
              onClick={() => openAuth("signup")}
            >
              {plan.cta}
            </Button>
          </div>
        ))}
      </StaggerList>

      <p className="text-center text-xs text-muted-foreground mt-6">
        All plans include a 5-credit free trial. No credit card required to sign up.
      </p>
    </div>
  </section>
);

/* ─── Testimonials ────────────────────────────────────────── */

const TestimonialsSection = () => (
  <section className="py-20 md:py-28">
    <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8">
      <FadeIn>
        <div className="text-center mb-14">
          <p className="text-sm font-semibold uppercase tracking-widest text-primary mb-3">
            Testimonials
          </p>
          <h2 className="text-3xl sm:text-4xl font-bold text-foreground">
            Recruiters who switched to Rankora
          </h2>
          <div className="flex justify-center gap-1 mt-3">
            {[...Array(5)].map((_, i) => (
              <Star
                key={i}
                className="h-4 w-4 text-warning fill-warning"
              />
            ))}
          </div>
        </div>
      </FadeIn>

      <StaggerList
        className="grid grid-cols-1 md:grid-cols-3 gap-6"
        stagger={0.1}
      >
        {testimonials.map((t) => (
          <div
            key={t.name}
            className="rounded-xl border border-border bg-card p-6 flex flex-col gap-4"
          >
            <Quote className="h-5 w-5 text-primary/40 shrink-0" />
            <p className="text-sm text-foreground leading-relaxed flex-1">
              "{t.quote}"
            </p>
            <div className="flex items-center gap-3 pt-2 border-t border-border">
              <div className="w-9 h-9 rounded-full bg-primary/15 text-primary text-xs font-bold flex items-center justify-center shrink-0">
                {t.initials}
              </div>
              <div>
                <p className="text-sm font-semibold text-foreground">
                  {t.name}
                </p>
                <p className="text-xs text-muted-foreground">{t.role}</p>
              </div>
            </div>
          </div>
        ))}
      </StaggerList>
    </div>
  </section>
);

/* ─── FAQ ─────────────────────────────────────────────────── */

const FaqItem = ({ q, a }: { q: string; a: string }) => {
  const [open, setOpen] = useState(false);
  return (
    <div className="rounded-lg border border-border bg-card overflow-hidden">
      <button
        onClick={() => setOpen((v) => !v)}
        className="w-full flex items-center justify-between px-5 py-4 text-left gap-4 hover:bg-muted/50 transition-colors"
        aria-expanded={open}
      >
        <span className="text-sm font-semibold text-foreground">{q}</span>
        {open ? (
          <ChevronUp className="h-4 w-4 text-muted-foreground shrink-0" />
        ) : (
          <ChevronDown className="h-4 w-4 text-muted-foreground shrink-0" />
        )}
      </button>
      {open && (
        <div className="px-5 pb-4">
          <p className="text-sm text-muted-foreground leading-relaxed">{a}</p>
        </div>
      )}
    </div>
  );
};

const FaqSection = () => (
  <section className="py-20 md:py-28 bg-muted" id="faq">
    <div className="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8">
      <FadeIn>
        <div className="text-center mb-12">
          <p className="text-sm font-semibold uppercase tracking-widest text-primary mb-3">
            FAQ
          </p>
          <h2 className="text-3xl sm:text-4xl font-bold text-foreground">
            Common questions
          </h2>
        </div>
      </FadeIn>
      <div className="space-y-2">
        {faqs.map((item) => (
          <FaqItem key={item.q} q={item.q} a={item.a} />
        ))}
      </div>
    </div>
  </section>
);

/* ─── CTA Banner ──────────────────────────────────────────── */

const CtaBannerSection = ({ openAuth }: { openAuth: OpenAuthFn }) => (
  <section
    className="py-20 md:py-28"
    style={{
      background:
        "linear-gradient(135deg, hsl(217,91%,20%), hsl(217,91%,35%))",
    }}
  >
    <div className="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
      <FadeIn>
        <h2 className="text-3xl sm:text-4xl font-bold text-white mb-4 leading-tight">
          Your next great hire is in that pile of resumes.
        </h2>
        <p className="text-base text-white/70 mb-8 max-w-xl mx-auto">
          Sign up free. Paste a JD. Upload resumes. Get a ranked shortlist in
          under 2 minutes — with strengths, gaps, and interview questions for
          every candidate.
        </p>
        <div className="flex flex-col sm:flex-row gap-3 justify-center">
          <Button
            size="lg"
            className="h-12 px-8 bg-white text-primary hover:bg-white/90 font-semibold"
            onClick={() => openAuth("signup")}
          >
            Start Free — No Card Needed <ArrowRight className="h-4 w-4" />
          </Button>
          <Button
            size="lg"
            variant="ghost"
            className="h-12 px-8 text-white hover:bg-white/10 border border-white/20"
            onClick={() => openAuth("signin")}
          >
            Sign In
          </Button>
        </div>
        <p className="mt-4 text-sm text-white/50">
          5 free credits · No credit card · Takes 30 seconds to set up
        </p>
      </FadeIn>
    </div>
  </section>
);

/* ─── Footer ──────────────────────────────────────────────── */

const LandingFooter = () => (
  <footer className="bg-muted border-t border-border py-12 md:py-16">
    <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
      <div className="grid grid-cols-2 md:grid-cols-4 gap-8 mb-10">
        {/* Brand */}
        <div className="col-span-2 md:col-span-1">
          <div className="flex items-center gap-2 mb-3">
            <div className="w-7 h-7 rounded-md bg-primary flex items-center justify-center">
              <Layers className="h-4 w-4 text-white" />
            </div>
            <span className="text-base font-bold tracking-tight text-foreground">
              Rankora
            </span>
          </div>
          <p className="text-sm text-muted-foreground leading-relaxed max-w-xs">
            AI-powered resume ranking for teams who hire seriously.
          </p>
          <div className="flex gap-3 mt-4">
            <a
              href="#"
              aria-label="Twitter"
              className="w-8 h-8 rounded-md bg-card border border-border flex items-center justify-center text-muted-foreground hover:text-foreground hover:border-primary/30 transition-colors"
            >
              <Twitter className="h-3.5 w-3.5" />
            </a>
            <a
              href="#"
              aria-label="LinkedIn"
              className="w-8 h-8 rounded-md bg-card border border-border flex items-center justify-center text-muted-foreground hover:text-foreground hover:border-primary/30 transition-colors"
            >
              <Linkedin className="h-3.5 w-3.5" />
            </a>
            <a
              href="#"
              aria-label="GitHub"
              className="w-8 h-8 rounded-md bg-card border border-border flex items-center justify-center text-muted-foreground hover:text-foreground hover:border-primary/30 transition-colors"
            >
              <Github className="h-3.5 w-3.5" />
            </a>
          </div>
        </div>

        {/* Product */}
        <div>
          <p className="text-xs font-semibold uppercase tracking-widest text-muted-foreground mb-4">
            Product
          </p>
          <ul className="space-y-2.5">
            {["Features", "Pricing", "Changelog", "Roadmap"].map((item) => (
              <li key={item}>
                <a
                  href="#"
                  className="text-sm text-muted-foreground hover:text-foreground transition-colors"
                >
                  {item}
                </a>
              </li>
            ))}
          </ul>
        </div>

        {/* Company */}
        <div>
          <p className="text-xs font-semibold uppercase tracking-widest text-muted-foreground mb-4">
            Company
          </p>
          <ul className="space-y-2.5">
            {["About", "Blog", "Careers", "Contact"].map((item) => (
              <li key={item}>
                <a
                  href="#"
                  className="text-sm text-muted-foreground hover:text-foreground transition-colors"
                >
                  {item}
                </a>
              </li>
            ))}
          </ul>
        </div>

        {/* Legal */}
        <div>
          <p className="text-xs font-semibold uppercase tracking-widest text-muted-foreground mb-4">
            Legal
          </p>
          <ul className="space-y-2.5">
            {["Privacy Policy", "Terms of Service", "Cookie Policy", "GDPR"].map(
              (item) => (
                <li key={item}>
                  <a
                    href="#"
                    className="text-sm text-muted-foreground hover:text-foreground transition-colors"
                  >
                    {item}
                  </a>
                </li>
              )
            )}
          </ul>
        </div>
      </div>

      <div className="pt-6 border-t border-border flex flex-col sm:flex-row items-center justify-between gap-2 text-xs text-muted-foreground">
        <span>
          &copy; {new Date().getFullYear()} Rankora. All rights reserved.
        </span>
        <span>
          Built by{" "}
          <a
            href="https://boldteq.com"
            target="_blank"
            rel="noopener noreferrer"
            className="text-foreground hover:text-primary transition-colors"
          >
            Boldteq
          </a>
        </span>
      </div>
    </div>
  </footer>
);

/* ─── Main Component ──────────────────────────────────────── */

const LandingPage = () => {
  const [authOpen, setAuthOpen] = useState(false);
  const [authTab, setAuthTab] = useState<"signin" | "signup">("signup");
  const [annual, setAnnual] = useState(false);

  const openAuth: OpenAuthFn = (tab = "signup") => {
    setAuthTab(tab);
    setAuthOpen(true);
  };

  const scrollTo = (id: string) => {
    document.getElementById(id)?.scrollIntoView({ behavior: "smooth" });
  };

  return (
    <div className="min-h-screen bg-background text-foreground">
      <LandingNav scrollTo={scrollTo} openAuth={openAuth} />
      <HeroSection openAuth={openAuth} scrollTo={scrollTo} />
      <StatsBar />
      <HowItWorksSection />
      <FeaturesSection />
      <ProductDemoSection openAuth={openAuth} />
      <PricingSection openAuth={openAuth} annual={annual} setAnnual={setAnnual} />
      <TestimonialsSection />
      <FaqSection />
      <CtaBannerSection openAuth={openAuth} />
      <LandingFooter />
      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab={authTab} />
    </div>
  );
};

export default LandingPage;

